import { z } from "zod";

const CONTROL_CHARS = /[\u0000-\u001f\u007f]/;

/** Short user-visible text generated by the model. It is always rendered as text, never HTML. */
export function safeText(max: number) {
  return z
    .string()
    .trim()
    .min(1)
    .max(max)
    .regex(/^[^\u0000-\u001f\u007f]+$/, "Control characters are not allowed");
}

export const optionalSafeText = (max: number) =>
  z
    .string()
    .trim()
    .max(max)
    .regex(/^[^\u0000-\u001f\u007f]*$/, "Control characters are not allowed")
    .optional();

/** Component references are opaque IDs issued by the API, never URLs or free-form selectors. */
export const refIdSchema = z
  .string()
  .min(1)
  .max(64)
  .regex(/^[A-Za-z0-9][A-Za-z0-9_-]*$/, "Expected an opaque entity ID");

export const PLANNING_QUESTION_IDS = [
  "arrival_date",
  "departure_date",
  "adults",
  "children",
  "child_ages",
  "budget_amount",
  "budget_currency",
  "budget_scope",
  "confirm_suggested_plan",
] as const;

export type PlanningQuestionId = (typeof PLANNING_QUESTION_IDS)[number];

export const planningQuestionIdSchema = z.enum(PLANNING_QUESTION_IDS);

export const planningQuestionKindSchema = z.enum(["date", "number", "text", "select", "boolean"]);

export const planningQuestionSchema = z.object({
  id: planningQuestionIdSchema,
  label: safeText(160),
  help: optionalSafeText(240),
  kind: planningQuestionKindSchema,
  required: z.boolean(),
  currentValue: z.union([z.string().max(300), z.number(), z.boolean(), z.null()]),
  options: z.array(z.object({ value: z.string().max(60), label: safeText(80) })).max(20).optional(),
  min: z.number().optional(),
  max: z.number().optional(),
});

export type PlanningQuestion = z.infer<typeof planningQuestionSchema>;

const safeAnswerText = (max: number) =>
  z
    .string()
    .max(max)
    .refine((value) => !CONTROL_CHARS.test(value), "Control characters are not allowed");

export const planningAnswerValueSchema = z.union([
  safeAnswerText(300),
  z.number().finite(),
  z.boolean(),
  z.array(safeAnswerText(80)).max(20),
  z.null(),
]);

export const planningAnswerSchema = z
  .object({
    questionId: planningQuestionIdSchema,
    value: planningAnswerValueSchema,
  })
  .strict();

export type PlanningAnswer = z.infer<typeof planningAnswerSchema>;

export const clarificationSubmissionSchema = z
  .object({
    answers: z.array(planningAnswerSchema).min(1).max(20),
  })
  .strict()
  .superRefine((submission, ctx) => {
    const seen = new Set<string>();
    for (const [index, answer] of submission.answers.entries()) {
      if (seen.has(answer.questionId)) {
        ctx.addIssue({ code: "custom", path: ["answers", index, "questionId"], message: "Each question may be answered once" });
      }
      seen.add(answer.questionId);
    }
  });

export type ClarificationSubmission = z.infer<typeof clarificationSubmissionSchema>;
